package com.primehr.learningdevelopment;
import com.primehr.learningdevelopment.api.LdFoundationDtos.*;import com.primehr.learningdevelopment.application.LdFoundationService;import com.primehr.learningdevelopment.domain.*;import com.primehr.shared.audit.PrimeHrAuditEventRepository;import com.primehr.shared.exception.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional
class LdFoundationIntegrationTest {
 @Autowired LdFoundationService service;@Autowired PrimeHrAuditEventRepository audit;
 @Test void policyIsVersionedEffectiveAndAgencyIsolated(){String a="LD-POLICY";PolicyResponse draft=service.createPolicy(a,policy("POL",null),"p-create");PolicyResponse published=service.publishPolicy(a,draft.id(),new PublishTransition(draft.recordVersion(),LocalDate.of(2026,1,1),null,"approved"),"p-publish");assertThat(service.effectivePolicy(a,LocalDate.of(2026,6,1)).id()).isEqualTo(published.id());assertThatThrownBy(()->service.updatePolicy(a,published.id(),policy("POL",published.recordVersion()),null)).isInstanceOf(IllegalLifecycleTransitionException.class);PolicyResponse revision=service.revisePolicy(a,published.id(),new DefinitionTransition(published.recordVersion(),"annual review"),null);PolicyResponse next=service.publishPolicy(a,revision.id(),new PublishTransition(revision.recordVersion(),LocalDate.of(2027,1,1),null,"approved"),null);assertThat(next.definitionVersion()).isEqualTo(2);assertThat(service.policy(a,published.id()).effectiveTo()).isEqualTo(LocalDate.of(2026,12,31));assertThatThrownBy(()->service.policy("OTHER",published.id())).isInstanceOf(ResourceNotFoundException.class);assertThat(audit.count()).isGreaterThanOrEqualTo(4);}
 @Test void catalogAndEvaluationDefinitionsAreImmutableAfterPublication(){String a="LD-DEFINITIONS";InterventionResponse intervention=service.createIntervention(a,new InterventionInput("COACH","Coaching",null,LdInterventionVersion.Category.COACHING,LdInterventionVersion.Modality.WORKPLACE,"Observed application","Supervisor availability",null),null);intervention=service.publishIntervention(a,intervention.id(),new PublishTransition(intervention.recordVersion(),LocalDate.of(2026,1,1),null,"approved"),null);InterventionResponse published=intervention;assertThatThrownBy(()->service.updateIntervention(a,published.id(),new InterventionInput("COACH","Changed",null,LdInterventionVersion.Category.COACHING,LdInterventionVersion.Modality.WORKPLACE,"Outcome",null,published.recordVersion()),null)).isInstanceOf(IllegalLifecycleTransitionException.class);EvaluationFrameworkResponse f=service.createEvaluationFramework(a,new EvaluationFrameworkInput("EVAL","CBLD evaluation",null,"Agency policy",null),null);f=service.replaceEvaluationLevels(a,f.id(),new EvaluationLevelsInput(f.recordVersion(),List.of(new EvaluationLevelInput(LdEvaluationLevel.Type.REACTION,true,0,LdEvaluationLevel.ScoreMethod.PERCENTAGE,new BigDecimal("80"),"Completed instrument","Use approved reaction form",1),new EvaluationLevelInput(LdEvaluationLevel.Type.BEHAVIOR_APPLICATION,true,120,LdEvaluationLevel.ScoreMethod.QUALITATIVE,null,"Supervisor evidence","Assess workplace application",2))),null);f=service.publishEvaluationFramework(a,f.id(),new PublishTransition(f.recordVersion(),LocalDate.of(2026,1,1),null,"approved"),null);assertThat(f.levels()).hasSize(2);EvaluationFrameworkResponse frozen=f;assertThatThrownBy(()->service.replaceEvaluationLevels(a,frozen.id(),new EvaluationLevelsInput(frozen.recordVersion(),frozen.levels().stream().map(x->new EvaluationLevelInput(LdEvaluationLevel.Type.valueOf(x.levelType()),x.required(),x.dueAfterDays(),LdEvaluationLevel.ScoreMethod.valueOf(x.scoreMethod()),x.passingScore(),x.evidenceRequirements(),x.instrumentGuidance(),x.displayOrder())).toList()),null)).isInstanceOf(IllegalLifecycleTransitionException.class);}
 @Test void providerResourcePersonRulesAndStaleWritesFailClosed(){String a="LD-REGISTRY";ProviderResponse p=service.createProvider(a,new ProviderInput("CSC","Civil Service Commission",LdProvider.Type.EXTERNAL_GOVERNMENT,null,null,null),null);ResourcePersonResponse r=service.createResourcePerson(a,new ResourcePersonInput("RP-1",LdResourcePerson.Source.EXTERNAL,null,"Resource Person",p.id(),"Leadership","Certified",null,null),null);assertThatThrownBy(()->service.providerStatus(a,p.id(),new RegistryTransition(p.recordVersion(),"inactive"),false,null)).hasMessageContaining("assigned");ProviderResponse updated=service.updateProvider(a,p.id(),new ProviderInput("CSC","CSC Regional Office",LdProvider.Type.EXTERNAL_GOVERNMENT,null,null,p.recordVersion()),null);assertThatThrownBy(()->service.updateProvider(a,p.id(),new ProviderInput("CSC","Stale",LdProvider.Type.EXTERNAL_GOVERNMENT,null,null,p.recordVersion()),null)).isInstanceOf(OptimisticConflictException.class);assertThat(updated.name()).isEqualTo("CSC Regional Office");assertThat(r.providerId()).isEqualTo(p.id());assertThatThrownBy(()->service.createResourcePerson(a,new ResourcePersonInput("BAD",LdResourcePerson.Source.EMPLOYEE,null,"Missing employee",null,null,null,null,null),null)).hasMessageContaining("employeeNo");}
 private PolicyInput policy(String code,Long version){return new PolicyInput(code,"Agency L&D policy",null,"CSC and agency policy",1,1,new BigDecimal("40.00"),90,180,true,true,true,version);}
}
